-- =====================================================================
--  06: imágenes de DEMO (ilustraciones sencillas) para productos, servicios y retos.
--  Se puede correr varias veces: solo agrega imagen a lo que no tiene. Borra con:
--    DELETE FROM publicacion_imagenes; DELETE FROM reto_imagenes;   (solo si quieres quitarlas)
--  Requiere haber corrido 02, 03 y 05 (en ese orden).
-- =====================================================================
BEGIN;
INSERT INTO publicacion_imagenes (publicacion_id, orden, mime, datos)
 SELECT p.id, 1, 'image/jpeg', decode('','base64') FROM publicaciones p
  WHERE p.titulo = 'Jabón de avena y miel' AND NOT EXISTS (SELECT 1 FROM publicacion_imagenes i WHERE i.publicacion_id = p.id);
